        (btnOneDisabled ? 'disabled' : '') +
        '>' +
        esc(btnOneLabel) +
        '</button>' +
        '<button type="button" class="fortune-buy-btn fortune-buy-btn--batch" data-action="' +
        esc(hatchBatchAction) +
        '" ' +
        (btnBatchDisabled ? 'disabled' : '') +
        '>' +
        esc(btnBatchLabel) +
        '</button></div></div>';
